-- PREVIEW ONLY: approval/tracking only; never proves disbursement or posts a ledger movement.
CREATE TABLE "salary_advances" ("id" BIGSERIAL PRIMARY KEY,"branch_id" BIGINT NOT NULL,"employee_id" UUID NOT NULL,"requested_amount_cents" BIGINT NOT NULL,"approved_amount_cents" BIGINT,"outstanding_amount_cents" BIGINT NOT NULL DEFAULT 0,"status" VARCHAR(20) NOT NULL DEFAULT 'requested',"notes" VARCHAR(500),"requested_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"approved_by" UUID,"approved_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "salary_advance_amounts" CHECK ("requested_amount_cents" > 0 AND "outstanding_amount_cents" >= 0 AND ("approved_amount_cents" IS NULL OR "approved_amount_cents" >= 0)),CONSTRAINT "salary_advance_status" CHECK ("status" IN ('requested','approved','rejected','cancelled')),FOREIGN KEY ("branch_id") REFERENCES "branches"("id") ON DELETE RESTRICT,FOREIGN KEY ("employee_id") REFERENCES "users"("id") ON DELETE RESTRICT,FOREIGN KEY ("approved_by") REFERENCES "users"("id") ON DELETE RESTRICT);
CREATE INDEX "salary_advances_employee_status_idx" ON "salary_advances"("employee_id","status");
ALTER TABLE "salary_advances" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE "salary_advances" FROM PUBLIC, anon, authenticated;
